public void processRecord(METActivateInventItemPriceSimContract _metActivateInventItemPriceSimContract)
{
    #OCCRetryCount

    try
    {
        METInventItemPriceSim metInventItemPriceSim;
        InventItemPriceSim inventItemPriceSim;

        while select metInventItemPriceSim
        {
            ttsbegin;

            buf2Buf(metInventItemPriceSim, inventItemPriceSim);

            if (inventItemPriceSim.validateWrite() && !InventItemPriceSim::find(inventItemPriceSim.ItemId, inventItemPriceSim.VersionId, inventItemPriceSim.FromDate, inventItemPriceSim.PriceType, inventItemPriceSim.InventDimId))
            {
                inventItemPriceSim.insert();
                InventItemPriceActivationJob::activateInventItemPriceSimExt(inventItemPriceSim);
            }               

            ttscommit;
        }
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch
    {
        throw error("@MET:UnhandledError");
    }
}
